/**
 * Shapes of the bundled model catalog.
 *
 * `rawModelsDevSchema` reads https://models.dev/api.json loosely (unknown
 * keys pass, only the fields Emperor projects are checked). The projected
 * snapshot is strict: it is generated by `sync.ts`, committed, and read by
 * `lookup.ts`, so any drift fails the sync or the snapshot test instead of
 * reaching the lookup. Field names stay models.dev's own (snake_case) so a
 * refresh diff reads against the upstream data directly.
 */
import { z } from 'zod'

const tokenCount = z.number().int().nonnegative()
const price = z.number().nonnegative()

const rawReasoningOptionSchema = z.looseObject({
  type: z.string(),
  values: z.array(z.string()).optional(),
  min: z.number().optional(),
  max: z.number().optional(),
})

const rawModelSchema = z.looseObject({
  id: z.string().min(1),
  name: z.string().optional(),
  family: z.string().optional(),
  tool_call: z.boolean().optional(),
  reasoning: z.boolean().optional(),
  reasoning_options: z.array(rawReasoningOptionSchema).optional(),
  temperature: z.boolean().optional(),
  release_date: z.string().optional(),
  status: z.string().optional(),
  canonical_model_id: z.string().optional(),
  modalities: z
    .looseObject({
      input: z.array(z.string()).optional(),
      output: z.array(z.string()).optional(),
    })
    .optional(),
  limit: z.looseObject({
    context: z.number().nonnegative(),
    input: z.number().nonnegative().optional(),
    output: z.number().nonnegative(),
  }),
  cost: z
    .looseObject({
      input: z.number().optional(),
      output: z.number().optional(),
      cache_read: z.number().optional(),
      cache_write: z.number().optional(),
    })
    .optional(),
})

export const rawModelsDevProviderSchema = z.looseObject({
  id: z.string().min(1),
  name: z.string().min(1),
  api: z.string().optional(),
  models: z.record(z.string(), rawModelSchema),
})

export type RawModelsDevProvider = z.infer<typeof rawModelsDevProviderSchema>

export const snapshotReasoningOptionSchema = z.strictObject({
  type: z.enum(['effort', 'toggle', 'budget_tokens']),
  values: z.array(z.string().min(1)).optional(),
  min: z.number().nonnegative().optional(),
  max: z.number().nonnegative().optional(),
})

export const snapshotModelSchema = z.strictObject({
  name: z.string().optional(),
  family: z.string().optional(),
  release_date: z
    .string()
    .regex(/^\d{4}-\d{2}(?:-\d{2})?$/)
    .optional(),
  status: z.string().optional(),
  limit: z.strictObject({
    context: tokenCount,
    input: tokenCount.optional(),
    output: tokenCount,
  }),
  modalities: z.strictObject({
    input: z.array(z.string()),
    output: z.array(z.string()),
  }),
  tool_call: z.boolean().optional(),
  reasoning: z.boolean().optional(),
  reasoning_options: z.array(snapshotReasoningOptionSchema).optional(),
  temperature: z.boolean().optional(),
  cost: z
    .strictObject({
      input: price.optional(),
      output: price.optional(),
      cache_read: price.optional(),
      cache_write: price.optional(),
    })
    .optional(),
  canonical_model_id: z.string().optional(),
})

export const snapshotProviderSchema = z.strictObject({
  name: z.string().min(1),
  api: z.string().optional(),
  models: z.record(z.string().min(1), snapshotModelSchema),
})

export const modelsDevSnapshotSchema = z.strictObject({
  schemaVersion: z.literal(1),
  source: z.url(),
  /** The data's licence notice travels with the bundled copy. */
  license: z.string().min(1),
  providers: z.record(z.string().min(1), snapshotProviderSchema),
})

export type SnapshotReasoningOption = z.infer<
  typeof snapshotReasoningOptionSchema
>
export type SnapshotModel = z.infer<typeof snapshotModelSchema>
export type SnapshotProvider = z.infer<typeof snapshotProviderSchema>
export type ModelsDevSnapshot = z.infer<typeof modelsDevSnapshotSchema>

export const modelMetadataManifestSchema = z.strictObject({
  schemaVersion: z.literal(1),
  source: z.url(),
  license: z.strictObject({ spdx: z.string().min(1), url: z.url() }),
  fetchedAt: z.iso.datetime(),
  snapshot: z.string().min(1),
  sha256: z.string().regex(/^[0-9a-f]{64}$/),
  bytes: z.number().int().positive(),
  providerCount: z.number().int().nonnegative(),
  modelCount: z.number().int().nonnegative(),
  providers: z.record(z.string(), z.number().int().nonnegative()),
})

export type ModelMetadataManifest = z.infer<typeof modelMetadataManifestSchema>
